// ----------------------------------------------------------------------------
// 3. Batch Registration Helper for bbhost (`decomp_add(vma + 0x400000, ...)` )
// ----------------------------------------------------------------------------
template <typename DecompAddFn>
inline size_t GXRegisterAllDecompiledFunctions(DecompAddFn&& decomp_add_fn, uint64_t image_base = kGXEbootDefaultImageBase) {
    for (size_t i = 0; i < kGXDecompiledFunctionCount; ++i) {
        const GXDecompiledFunctionEntry& e = kGXDecompiledFunctions[i];
        decomp_add_fn(e.vma + image_base, e.size, e.func_ptr, e.name);
    }
    return kGXDecompiledFunctionCount;
}

#define GX_REGISTER_ALL_DECOMPILED_FUNCTIONS(decomp_add_callable) \
    do { \
        for (size_t _gx_i = 0; _gx_i < kGXDecompiledFunctionCount; ++_gx_i) { \
            const auto& _gx_e = kGXDecompiledFunctions[_gx_i]; \
            decomp_add_callable(_gx_e.vma + 0x400000ULL, _gx_e.size, _gx_e.func_ptr, _gx_e.name); \
        } \
    } while (0)

